package com.englishhero.wall;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.englishhero.identity.SessionPrincipal;
import static com.englishhero.wall.WallDtos.*;
@Service
public class WallInteractionService {
 private final WallMapper mapper;private final WallInteractionMapper comments;private final WallService messages;private final WallCommandService commands;
 public WallInteractionService(WallMapper mapper,WallInteractionMapper comments,WallService messages,WallCommandService commands){this.mapper=mapper;this.comments=comments;this.messages=messages;this.commands=commands;}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public Object like(SessionPrincipal actor,String id,LikeInput input){long uid=commands.actor(actor),target=WallRules.id(id,"id");if(input==null||input.liked()==null)throw com.englishhero.web.BusinessException.invalid("liked","请选择点赞状态");commands.lock(uid);var p=messages.visible(target,true);if(input.liked())mapper.sql().update("INSERT INTO wall_like(user_id,message_id,created_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE user_id=user_id",uid,target,Timestamp.from(commands.clock.instant()));else mapper.sql().update("DELETE FROM wall_like WHERE user_id=? AND message_id=?",uid,target);return mapper.dto(p,uid);}
 @Transactional(readOnly=true)public Page<CommentDto> list(SessionPrincipal actor,String id,String cursor,int size){if(actor!=null)commands.actor(actor);messages.visible(WallRules.id(id,"id"),false);WallRules.size(size);var rows=comments.list(Long.parseLong(id),WallRules.cursor(cursor),size,false);boolean more=rows.size()>size;var items=rows.stream().limit(size).map(c->comments.dto(c,actor==null?null:actor.userId())).toList();return new Page<>(items,more?items.getLast().id():null,more);}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public CommentDto create(SessionPrincipal actor,String id,CommentInput input){long uid=commands.actor(actor),target=WallRules.id(id,"id");if(input==null)throw WallRules.missing();var p=new CommentInput(WallRules.uuid(input.requestId()),WallRules.text(input.text(),"text",500,true));return commands.execute(actor,p.requestId(),"CREATE_COMMENT:"+id,p,CommentDto.class,()->{messages.visible(target,true);commands.quota(uid,"COMMENT");long cid=mapper.insertKey("INSERT INTO wall_comment(message_id,user_id,body,created_at,updated_at) VALUES(?,?,?,?,?)",target,uid,p.text(),Timestamp.from(commands.clock.instant()),Timestamp.from(commands.clock.instant()));return comments.dto(comments.comment(cid,true),uid);});}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public Map<?,?> delete(SessionPrincipal actor,String id,Command input){long uid=commands.actor(actor),target=WallRules.id(id,"id");if(input==null)throw WallRules.conflict();long version=WallRules.version(input.expectedVersion());return commands.execute(actor,input.requestId(),"DELETE_COMMENT:"+id,input,Map.class,()->{var preliminary=comments.comment(target,false);if(preliminary==null||preliminary.userId()!=uid)throw WallRules.missing();var parent=mapper.message(preliminary.messageId(),true);if(parent==null||parent.status().equals("DELETED"))throw WallRules.missing();var c=comments.comment(target,true);if(c==null||c.status().equals("DELETED"))throw WallRules.missing();if(c.version()!=version)throw WallRules.conflict();mapper.sql().update("UPDATE wall_comment SET status='DELETED',version=version+1,updated_at=? WHERE id=?",Timestamp.from(commands.clock.instant()),target);return Map.of("id",id,"deleted",true);});}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public Map<?,?> report(SessionPrincipal actor,ReportInput input){long uid=commands.actor(actor);if(input==null)throw WallRules.missing();String type=WallRules.oneOf(input.targetType(),"targetType","MESSAGE","COMMENT"),reason=WallRules.oneOf(input.reason(),"reason","SPAM","UNFRIENDLY","PRIVACY","OTHER"),detail=WallRules.text(input.detail(),"detail",500,false);long target=WallRules.id(input.targetId(),"targetId");var p=new ReportInput(WallRules.uuid(input.requestId()),type,input.targetId(),reason,detail);return commands.execute(actor,p.requestId(),"REPORT",p,Map.class,()->{Long cid=null;long mid=target;if(type.equals("COMMENT")){var c=comments.comment(target,false);if(c==null)throw WallRules.missing();mid=c.messageId();cid=target;}messages.visible(mid,true);if(cid!=null){var c=comments.comment(cid,true);if(c==null||!c.status().equals("VISIBLE"))throw WallRules.missing();}String pending=type+":"+target;var exists=mapper.sql().queryForList("SELECT id FROM wall_report WHERE user_id=? AND pending_key=? FOR UPDATE",String.class,uid,pending);if(!exists.isEmpty())return Map.of("id",exists.getFirst(),"status","PENDING");commands.quota(uid,"REPORT");long rid=mapper.insertKey("INSERT INTO wall_report(user_id,message_id,comment_id,target_type,reason,detail,created_at) VALUES(?,?,?,?,?,?,?)",uid,mid,cid,type,reason,detail,Timestamp.from(commands.clock.instant()));return Map.of("id",Long.toString(rid),"status","PENDING");});}
}
